{"research_date": "2026-09-10", "pairs": [{"pair_id": "conflict_3dae9a3d4e82a70672819f7d", "claim_ids": ["claim_9039d913db542b25c47e6ea0", "claim_a0bb7087cfcd67fde808054f"], "query_ids": ["q_311"], "claims": [{"claim_id": "claim_9039d913db542b25c47e6ea0", "quote": "The automobile manufacturer may apply for an import adjustment offset amount equal to 2.5 percent of the aggregate MSRP value of all automobiles assembled in the United States from May 1, 2026, through April 30, 2027.", "url": "https://www.whitehouse.gov/presidential-actions/2025/04/amendments-to-adjusting-imports-of-automobiles-and-automobile-parts-into-the-united-states", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"duty_rate": "2.5 percent", "effective_date": "May 1, 2026", "expiration_date": "April 30, 2027"}}, {"claim_id": "claim_a0bb7087cfcd67fde808054f", "quote": "2.5% of aggregate MSRP for eligible autos assembled between May 1, 2026, and April 30, 2027", "url": "https://www.trade.gov/press-release/department-commerce-announces-new-auto-tariff-offset-process", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"tariff_program": "import adjustment offset amounts", "duty_rate": "2.5%", "effective_date": "May 1, 2026", "expiration_date": "April 30, 2027"}}]}, {"pair_id": "conflict_d065eb9aefbd6e47ab4b5ea7", "claim_ids": ["claim_67bd0d01b357e3642b1a053b", "claim_f6ecb0f1f9d7fb544193404f"], "query_ids": ["q_312"], "claims": [{"claim_id": "claim_67bd0d01b357e3642b1a053b", "quote": "On March 26, 2025, the President issued Proclamation 10908, “Adjusting Imports of Automobiles and Automobile Parts Into the United States,” finding that imports of automobiles and certain automobile parts continue to threaten to impair the national security of the United States", "url": "https://www.federalregister.gov/documents/2025/05/20/2025-08917/procedures-for-submissions-by-importers-of-automobiles-qualifying-for-preferential-tariff-treatment", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"legal_authority": "Proclamation 10908 consistent with section 232 of the Trade Expansion Act of 1962, as amended (19 U.S.C. 1862)", "announcement_date": "March 26, 2025"}}, {"claim_id": "claim_f6ecb0f1f9d7fb544193404f", "quote": "The Secretary may retroactively extend this treatment to qualifying model lines for vehicles imported on or after April 3, 2025, at his discretion.", "url": "https://www.federalregister.gov/documents/2025/05/20/2025-08917/procedures-for-submissions-by-importers-of-automobiles-qualifying-for-preferential-tariff-treatment", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"effective_date": "April 3, 2025", "reported_policy_status": "proposed regulation"}}]}, {"pair_id": "conflict_6846e97d828fdfbee25dc514", "claim_ids": ["claim_078e7082229dda559eb142d8", "claim_600788deebbdd6168a63ede8"], "query_ids": ["q_312"], "claims": [{"claim_id": "claim_078e7082229dda559eb142d8", "quote": "Pursuant to President Donald J. Trump’s proclamation on March 26, 2025, 25% tariffs on imports of automobile parts went into effect on May 3, 2025.", "url": "https://www.trade.gov/press-release/department-commerce-announces-new-auto-tariff-offset-process", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"tariff_program": "Section 232 tariffs", "duty_rate": "25%", "effective_date": "May 3, 2025"}}, {"claim_id": "claim_600788deebbdd6168a63ede8", "quote": "The Proclamation imposed a 25 percent tariff on certain imports of automobiles, effective April 3, 2025, and certain imports of auto parts, effective May 3, 2025.", "url": "https://www.federalregister.gov/documents/2025/05/20/2025-08917/procedures-for-submissions-by-importers-of-automobiles-qualifying-for-preferential-tariff-treatment", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"duty_rate": "25 percent", "effective_date": "April 3, 2025"}}]}, {"pair_id": "conflict_d271695f64d4eb1e0b85c849", "claim_ids": ["claim_9be0456ee416afb3a0cfe4f7", "claim_c8d620d507914aa530f9edd8"], "query_ids": ["q_312"], "claims": [{"claim_id": "claim_9be0456ee416afb3a0cfe4f7", "quote": "For the purposes of the notice, only automobiles imported from Mexico and Canada that qualify for preferential treatment under USMCA may be eligible to apply the additional tariff exclusively to the value of the non-U.S. content of the automobile.", "url": "https://www.federalregister.gov/documents/2025/05/20/2025-08917/procedures-for-submissions-by-importers-of-automobiles-qualifying-for-preferential-tariff-treatment", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {}}, {"claim_id": "claim_c8d620d507914aa530f9edd8", "quote": "Only vehicles imported from Mexico and Canada that qualify for preferential tariff treatment under the USMCA may be found to be eligible to apply the additional tariff exclusively to the value of the non-U.S. content of the automobile.", "url": "https://www.federalregister.gov/documents/2025/05/20/2025-08917/procedures-for-submissions-by-importers-of-automobiles-qualifying-for-preferential-tariff-treatment", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {}}]}, {"pair_id": "conflict_f93e649bb830b723d43bba85", "claim_ids": ["claim_b8affe397043ad88778b23e8", "claim_ef51deac8255c77617fc6781"], "query_ids": ["q_312"], "claims": [{"claim_id": "claim_b8affe397043ad88778b23e8", "quote": "The additional tariff will apply exclusively to the value of the non-U.S. content for the relevant model line.", "url": "https://www.federalregister.gov/documents/2025/05/20/2025-08917/procedures-for-submissions-by-importers-of-automobiles-qualifying-for-preferential-tariff-treatment", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {}}, {"claim_id": "claim_ef51deac8255c77617fc6781", "quote": "The additional tariff will apply exclusively to the value of the non-U.S. content for the relevant model line.", "url": "https://www.federalregister.gov/documents/2025/05/20/2025-08917/procedures-for-submissions-by-importers-of-automobiles-qualifying-for-preferential-tariff-treatment", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"duty_rate": "25 percent"}}]}, {"pair_id": "conflict_ef1c086b04d016e644ad0df5", "claim_ids": ["claim_32b753e30e77e09d6cb403bf", "claim_c523f32161ad5b8eb4b5d62f"], "query_ids": ["q_312"], "claims": [{"claim_id": "claim_32b753e30e77e09d6cb403bf", "quote": "ITA will accept the applications in four scheduled submission windows every year and then post the applications for public review.", "url": "https://www.whitecase.com/insight-alert/commerce-department-opens-new-automobile-parts-section-232-tariff-inclusions-process", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 232 tariffs"}}, {"claim_id": "claim_c523f32161ad5b8eb4b5d62f", "quote": "After receiving the applications, ITA will have 60 days to review and publish a determination.", "url": "https://www.whitecase.com/insight-alert/commerce-department-opens-new-automobile-parts-section-232-tariff-inclusions-process", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 232 tariffs"}}]}, {"pair_id": "conflict_c232b4f5d5c3e7a2e88d8a7f", "claim_ids": ["claim_035802c6a30a1c0e956a7cc1", "claim_a3b4846f4cd8e94e931cff67"], "query_ids": ["q_313"], "claims": [{"claim_id": "claim_035802c6a30a1c0e956a7cc1", "quote": "Bonded warehouses allow importers to defer duty payments for up to five years, freeing up capital that would otherwise be tied up in customs duties.", "url": "https://geodis.com/us-en/resources/blog/warehousing-and-value-added-logistics-expertise/bonded-warehouses-manage-us-tariffs", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "bonded warehouse"}}, {"claim_id": "claim_a3b4846f4cd8e94e931cff67", "quote": "Pay duties at the rate in effect when goods are withdrawn from the bonded warehouse, potentially benefiting from future tariff reductions", "url": "https://geodis.com/us-en/resources/blog/warehousing-and-value-added-logistics-expertise/bonded-warehouses-manage-us-tariffs", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "bonded warehouse", "duty_rate": "rate in effect when goods are withdrawn"}}]}, {"pair_id": "conflict_6b8c0cc31fb66cb5a904509e", "claim_ids": ["claim_59cd0e4ed1748a67581f7292", "claim_d7448557ad6496feb0279f1a"], "query_ids": ["q_313"], "claims": [{"claim_id": "claim_59cd0e4ed1748a67581f7292", "quote": "Section 301 merchandise must be admitted to a zone in privileged foreign status, which locks its rate at admission, and the duty is collected when the goods enter US commerce. The zone defers the payment and freezes the rate; it does not remove the tariff.", "url": "https://www.platton.ai/insights/warehouse-and-fulfilment/mitigating-tariff-impacts-bonded-warehouses-ftz", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 301"}}, {"claim_id": "claim_d7448557ad6496feb0279f1a", "quote": "If tariff rates decrease during storage, you'll pay the lower duty rate when withdrawing goods for consumption.", "url": "https://geodis.com/us-en/resources/blog/warehousing-and-value-added-logistics-expertise/bonded-warehouses-manage-us-tariffs", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {}}]}, {"pair_id": "conflict_db5bb72c2fb7b73842ea8782", "claim_ids": ["claim_08e557ced3646a64c0872dcd", "claim_cc7f0ca2c35375c8b8d6a49a"], "query_ids": ["q_314"], "claims": [{"claim_id": "claim_08e557ced3646a64c0872dcd", "quote": "Section 301: Four-Year Review (50%) Forced labour (12.5%) MFN (7%) | 69.5% | Section 301 four-year review tariff increased to 50% from 1 January 2026.", "url": "https://www.china-briefing.com/news/us-china-tariff-rates-2025", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 301: Four-Year Review", "duty_rate": "50%", "effective_date": "1 January 2026"}}, {"claim_id": "claim_cc7f0ca2c35375c8b8d6a49a", "quote": "UPDATE: (2 June 2026): The US Trade Representative (USTR) has proposed a new tariff of 12.5 percent on China as a result of a Section 301 investigation into forced labour.", "url": "https://www.china-briefing.com/news/us-china-tariff-rates-2025", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 301", "duty_rate": "12.5 percent", "reported_policy_status": "proposed"}}]}, {"pair_id": "conflict_09c05dc31bfb3ca71ed496d7", "claim_ids": ["claim_dc90fe23d8bcecbbf24a15d7", "claim_f375be7bf84463b9427a10e3"], "query_ids": ["q_314"], "claims": [{"claim_id": "claim_dc90fe23d8bcecbbf24a15d7", "quote": "The industry will begin paying a 25% tariff on automotive parts as of May 3, 2025.", "url": "https://www.plantemoran.com/explore-our-thinking/insight/2025/05/adjusting-automobile-and-automobile-parts-tariffs-action", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 232", "affected_product": "automotive parts", "duty_rate": "25%", "effective_date": "May 3, 2025"}}, {"claim_id": "claim_f375be7bf84463b9427a10e3", "quote": "On 26 March 2025, Trump announced a 25 percent tariff on imports of automobiles and automobile parts from all trade partners, effective 3 April 2025. Many vehicles and vehicle parts coming from China were already subject to tariffs of up to 25 percent under Section 301.", "url": "https://www.china-briefing.com/news/us-china-tariff-rates-2025", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 301", "affected_product": "vehicles and vehicle parts", "duty_rate": "up to 25 percent", "announcement_date": "26 March 2025", "effective_date": "3 April 2025"}}]}]}

